    add  t0, t0, t1
    add  t0, t0, t2
    add  t0, t0, t4
    xor  t3, t0, a5
    .rept 5
    nop
    .endr
    beq  s1, s9, .LloopC24x
    j    .LloopC24
.LloopC24x:
/* C slot D (measure) */
    sw   t3, 0(a6)
    lw   t0, 0(s1)
    lw   t1, 0(s2)
    lw   t2, 0(s3)
    lw   t4, 0(s4)
    nop
    nop
    add  t0, t0, t1
    add  t0, t0, t2
    add  t0, t0, t4
    xor  t3, t0, a5
    csrr t5, 0x7e2
    sub  t5, a1, t5
    sltiu t6, t5, 25
    beqz t6, .LhC24
.LbC24:
    slli t5, t5, 2
    sub  t6, s10, t5
    nop
    .rept 6
    nop
    .endr
/* C slot E (jump into the next sled; its length is the sync) */
    sw   t3, 0(a6)
    nop
    nop
    lw   t0, 0(s5)
    lw   t1, 0(s6)
    lw   t2, 0(s7)
    lw   t4, 0(s8)
    add  t0, t0, t1
    add  t0, t0, t2
    add  t0, t0, t4
    xor  t3, t0, a5
    nop
    jalr x0, 0(t6)
.LxC24:
    j    lutg24_exit
.LhC24:
    bgtz t5, .LhC24e
    lw   t6, LATE(s0)
    addi t6, t6, 1
    sw   t6, LATE(s0)
    li   t5, 0
    j    .LbC24
.LhC24e:
    csrr t6, 0x7e2
    sub  t5, a1, t6
    li   t6, 24
    blt  t6, t5, .LhC24e
    j    .LbC24
.LsC24:
    li   t5, 2
    sw   t5, EXITC(s0)
    j    lutg24_exit
lutg24_exit:
    sw   s11, QW(s0)
    sw   a7, QR(s0)
    sw   a0, RECP(s0)
    lw   ra, 0(sp)
    lw   s0, 4(sp)
    lw   s1, 8(sp)
    lw   s2, 12(sp)
    lw   s3, 16(sp)
    lw   s4, 20(sp)
    lw   s5, 24(sp)
    lw   s6, 28(sp)
    lw   s7, 32(sp)
    lw   s8, 36(sp)
    lw   s9, 40(sp)
    lw   s10, 44(sp)
    lw   s11, 48(sp)
    lw   gp, 52(sp)
    lw   tp, 56(sp)
    addi sp, sp, 64
    li   a0, 0
    ret
    .size lutg_run_p24, . - lutg_run_p24

